#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("USAGE\n");
        return 1;
    }
    char *pattern = argv[1];
    char *string = argv[2];
    int pattern_len = strlen(pattern);
    int string_len = strlen(string);
    int match = 0;
    for (int i = 0; i < string_len; i++) {
        if (pattern[0] == '*' && pattern[1] == '\0') {
            match = 1;
            break;
        }
        if (pattern[0] == '?' || pattern[0] == string[i]) {
            if (pattern_len == 1) {
                match = 1;
                break;
            }
            pattern++;
            pattern_len--;
        } else if (pattern[0] == '*') {
            pattern++;
            pattern_len--;
            if (pattern_len == 0) {
                match = 1;
                break;
            }
            for (int j = i; j < string_len; j++) {
                int temp_match = 0;
                char *temp_pattern = pattern;
                int temp_pattern_len = pattern_len;
                for (int k = j; k < string_len; k++) {
                    if (*temp_pattern == '?' || *temp_pattern == string[k]) {
                        if (temp_pattern_len == 1) {
                            temp_match = 1;
                            break;
                        }
                        temp_pattern++;
                        temp_pattern_len--;
                    } else {
                        break;
                    }
                }
                if (temp_match) {
                    match = 1;
                    break;
                }
            }
        } else {
            break;
        }
    }
    if (match) {
        printf("MATCH\n");
    } else {
        printf("NO_MATCH\n");
    }
    return 0;
}
